class Solution {public int[][] solve(GraphNode graph){if(graph==null)return new int[0][0];IdentityHashMap<GraphNode,Integer> id=new IdentityHashMap<>();ArrayList<GraphNode> q=new ArrayList<>();q.add(graph);id.put(graph,0);for(int i=0;i<q.size();i++)for(GraphNode v:q.get(i).neighbors)if(!id.containsKey(v)){id.put(v,q.size());q.add(v);}int[][] out=new int[q.size()][q.size()];for(int i=0;i<q.size();i++)for(GraphNode v:q.get(i).neighbors)out[i][id.get(v)]++;return out;}}